  "public/zavi-picker.js": "/* Zavi element picker — dev tooling, inert outside the Zavi builder preview.\n *\n * Lets you click an element in the Zavi preview and have the AI edit exactly\n * that part of your app. Removed automatically when you export this repo to\n * your own GitHub, so it never ships with code you own.\n *\n * Safe by construction:\n *  - Does nothing at all unless this page is framed (top-level visits: no-op).\n *  - Sends only a CSS SELECTOR and a tag name. Never page text, never input\n *    values, never a DOM dump. Nothing it emits can carry personal data.\n *  - Only ever posts to the exact parent origin that handshook with it, never\n *    to \"*\", so the selector cannot be broadcast to a third party.\n */\n(function () {\n  \"use strict\";\n\n  // Not framed → this is a real visitor on the real site. Do nothing.\n  if (window.parent === window) return;\n\n  var READY = \"zavi:picker-ready\";\n  var SET = \"zavi:picker-set\";\n  var PICKED = \"zavi:element-picked\";\n\n  var parentOrigin = null; // learned from the parent's first message\n  var enabled = false;\n  var hovered = null;\n  var HIGHLIGHT = \"2px solid #d94f2b\";\n  var prevOutline = \"\";\n\n  /** Short, stable, structural selector. Never reads text or input values. */\n  function selectorFor(el) {\n    if (!el || el === document.body || el === document.documentElement) return null;\n\n    // An id is unique and shortest.\n    if (el.id && /^[A-Za-z0-9_-]+$/.test(el.id)) return \"#\" + el.id;\n\n    var parts = [];\n    var node = el;\n    var depth = 0;\n\n    while (node && node.nodeType === 1 && node !== document.body && depth < 4) {\n      var tag = node.tagName.toLowerCase();\n      var part = tag;\n\n      // Prefer a test id, then a plain class. Both are structural.\n      var testId = node.getAttribute(\"data-testid\");\n      if (testId && /^[A-Za-z0-9_-]+$/.test(testId)) {\n        part = tag + \"[data-testid=\" + testId + \"]\";\n      } else if (node.classList && node.classList.length) {\n        var cls = null;\n        for (var i = 0; i < node.classList.length; i++) {\n          if (/^[A-Za-z0-9_-]+$/.test(node.classList[i])) {\n            cls = node.classList[i];\n            break;\n          }\n        }\n        if (cls) part = tag + \".\" + cls;\n      }\n\n      parts.unshift(part);\n\n      // An id or test id anchors the selector — stop climbing.\n      if (part.indexOf(\"[data-testid=\") !== -1) break;\n\n      node = node.parentElement;\n      depth++;\n    }\n\n    return parts.length ? parts.join(\" \") : null;\n  }\n\n  function clearHighlight() {\n    if (hovered) {\n      hovered.style.outline = prevOutline;\n      hovered = null;\n    }\n  }\n\n  function onOver(e) {\n    if (!enabled) return;\n    var el = e.target;\n    if (!el || el.nodeType !== 1 || el === hovered) return;\n    clearHighlight();\n    hovered = el;\n    prevOutline = el.style.outline;\n    el.style.outline = HIGHLIGHT;\n  }\n\n  function onClick(e) {\n    if (!enabled || !parentOrigin) return;\n    var selector = selectorFor(e.target);\n    if (!selector) return;\n\n    e.preventDefault();\n    e.stopPropagation();\n\n    // Targeted post — never \"*\". Selector + tag only.\n    window.parent.postMessage(\n      { type: PICKED, selector: selector, tag: e.target.tagName.toLowerCase() },\n      parentOrigin\n    );\n\n    setEnabled(false);\n  }\n\n  function setEnabled(next) {\n    enabled = !!next;\n    if (!enabled) clearHighlight();\n    document.documentElement.style.cursor = enabled ? \"crosshair\" : \"\";\n  }\n\n  window.addEventListener(\"message\", function (event) {\n    if (!event.data || event.data.type !== SET) return;\n    // First contact defines the only parent we will ever talk to.\n    if (parentOrigin === null) parentOrigin = event.origin;\n    if (event.origin !== parentOrigin) return;\n    setEnabled(event.data.enabled);\n  });\n\n  document.addEventListener(\"mouseover\", onOver, true);\n  document.addEventListener(\"click\", onClick, true);\n\n  // Announce availability. Carries no data, so \"*\" leaks nothing — and it lets\n  // the parent show the picker affordance only when an app can actually serve it.\n  window.parent.postMessage({ type: READY }, \"*\");\n})();\n",
  "tailwind.config.ts": "import type { Config } from \"tailwindcss\";\nimport animate from \"tailwindcss-animate\";\n\nconst config: Config = {\n  darkMode: [\"class\"],\n  content: [\n    \"./app/**/*.{js,ts,jsx,tsx,mdx}\",\n    \"./lib/**/*.{js,ts,jsx,tsx,mdx}\",\n  ],\n  theme: {\n    extend: {},\n  },\n  plugins: [animate],\n};\n\nexport default config;\n",
